import{_ as d,C as l,o as i,c as o,a3 as h,E as n,j as e,a as r}from"./chunks/framework.Ba39LDvt.js";const E=JSON.parse('{"title":"数字电路自学","description":"从 HDLBits 和 Verilog 出发，经数字系统公开课、仿真与 FPGA 实践进入完整硬件设计。","frontmatter":{"title":"数字电路自学","description":"从 HDLBits 和 Verilog 出发，经数字系统公开课、仿真与 FPGA 实践进入完整硬件设计。"},"headers":[],"relativePath":"self-learning/digital.md","filePath":"self-learning/digital.md","lastUpdated":1795513256000}'),s={name:"self-learning/digital.md"};function c(g,t,b,p,f,u){const a=l("CourseTable");return i(),o("div",null,[t[0]||(t[0]=h('<h1 id="数字电路自学" tabindex="-1">数字电路自学 <a class="header-anchor" href="#数字电路自学" aria-label="Permalink to &quot;数字电路自学&quot;">​</a></h1><p>数字电路不是把软件代码换一种语法。硬件描述语言（Hardware Description Language，HDL）描述并行电路，寄存器在时钟边沿更新，组合路径有延迟。推荐顺序是<strong>逻辑概念 → 小模块 HDL → 测试平台 → 时序分析 → 系统集成</strong>。可与 <a href="/shanghaitech-ic-wiki-dev.github.io/map/digital">数字学习地图</a> 配合使用。</p><h2 id="入门-先会描述和检查小电路" tabindex="-1">入门：先会描述和检查小电路 <a class="header-anchor" href="#入门-先会描述和检查小电路" aria-label="Permalink to &quot;入门：先会描述和检查小电路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://hdlbits.01xz.net/" target="_blank" rel="noreferrer">HDLBits</a></td><td>在线练习</td><td>入门</td><td>从组合逻辑、计数器到有限状态机；做完后画出对应电路，而非只记录通过状态</td></tr><tr><td>Harris、Harris《Digital Design and Computer Architecture》</td><td>教材</td><td>入门—进阶</td><td>把逻辑、HDL 与处理器数据通路串起来；选择与自己指令集目标匹配的版本</td></tr><tr><td>Verilog / SystemVerilog 语言基础</td><td>语言与规范</td><td>入门—进阶</td><td>优先掌握位宽、符号、阻塞与非阻塞赋值、组合与时序过程；语言标准可从 <a href="https://www.accellera.org/" target="_blank" rel="noreferrer">Accellera</a> 查找入口</td></tr><tr><td><a href="https://6191.mit.edu/" target="_blank" rel="noreferrer">MIT 6.191（原 6.004）</a></td><td>数字系统课程</td><td>入门—进阶</td><td>自底向上学习逻辑、状态机与处理器；<a href="https://computationstructures.org/" target="_blank" rel="noreferrer">Computation Structures</a> 保留旧版公开材料</td></tr></tbody></table><p>每个练习都问三个问题：这里需要几个寄存器？复位后状态是什么？输出在哪个周期有效？特别检查位宽扩展、默认赋值、锁存器推断与复位优先级。测试要覆盖连续输入、空闲间隔和边界情况，不要只用一条“正常路径”。</p><h2 id="进阶-从语法走向可实现的系统" tabindex="-1">进阶：从语法走向可实现的系统 <a class="header-anchor" href="#进阶-从语法走向可实现的系统" aria-label="Permalink to &quot;进阶：从语法走向可实现的系统&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://www2.eecs.berkeley.edu/Courses/EECS151/" target="_blank" rel="noreferrer">UCB EECS151</a></td><td>数字设计与集成电路课程</td><td>进阶</td><td>连接 RTL、存储模块、流水线、FPGA / ASIC 方法与物理约束</td></tr><tr><td><a href="https://www.veripool.org/verilator/" target="_blank" rel="noreferrer">Verilator</a></td><td>编译型仿真工具</td><td>进阶</td><td>适合构建较大的自动化回归；注意支持的语言特性与时间模型需查当前文档</td></tr><tr><td><a href="https://www.cocotb.org/" target="_blank" rel="noreferrer">cocotb</a></td><td>Python 验证框架</td><td>进阶</td><td>用参考模型、随机输入和自动检查测试 HDL；底层仍需支持的仿真器</td></tr><tr><td><a href="https://www.chisel-lang.org/" target="_blank" rel="noreferrer">Chisel</a></td><td>Scala 硬件构造语言</td><td>进阶</td><td>适合参数化与生成式设计；先能读生成 RTL，再学习抽象与组件化</td></tr><tr><td><a href="https://spinalhdl.github.io/SpinalDoc-RTD/" target="_blank" rel="noreferrer">SpinalHDL</a></td><td>Scala 硬件构造语言</td><td>进阶</td><td>可用于总线、流水线及接口组织；同样不能绕过 HDL 与时序基础</td></tr></tbody></table><p>SystemVerilog 不等于完整验证环境，Chisel / SpinalHDL 也不等于自动获得正确电路。初学者宜先用一种语言完成模块与验证，再因参数化或工程需求引入生成器。综合后检查资源与关键路径；功能仿真通过不能证明时序满足要求，更不能证明跨时钟域（Clock Domain Crossing，CDC）安全。</p><h2 id="实践-先仿真-再上板-最后扩成系统" tabindex="-1">实践：先仿真，再上板，最后扩成系统 <a class="header-anchor" href="#实践-先仿真-再上板-最后扩成系统" aria-label="Permalink to &quot;实践：先仿真，再上板，最后扩成系统&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/eda/open-source">开源仿真工具链</a></td><td>本地实验</td><td>入门</td><td>Icarus Verilog 与波形查看器足以开始计数器、状态机和 FIFO 实验</td></tr><tr><td><a href="https://digilent.com/" target="_blank" rel="noreferrer">Digilent</a> 等厂商的 FPGA 开发板资料</td><td>板卡与参考设计</td><td>入门—进阶</td><td>选有原理图、引脚约束、时钟说明和工具支持的板卡，优先使用课程指定硬件</td></tr><tr><td>FPGA 厂商工具与板卡手册</td><td>工程实践</td><td>进阶</td><td>AMD Vivado、Intel Quartus 等依目标器件选择；烧录前检查电平、引脚与复位</td></tr><tr><td><a href="https://ysyx.oscc.cc/" target="_blank" rel="noreferrer">一生一芯</a></td><td>处理器与系统项目</td><td>进阶—深入</td><td>连接 C、指令集、处理器、验证与系统软件，参见 <a href="/shanghaitech-ic-wiki-dev.github.io/competitions/ysyx">项目介绍</a></td></tr></tbody></table><p>建议第一项作品是同步 FIFO：明确容量、满空行为、同时读写规则；写参考队列与自动比较；覆盖复位、绕回和满空边界。第二项再做 UART 或简单处理器。FPGA 上板前先完成仿真，上板后记录约束、时钟频率和时序报告；LED 亮了只是一个观察，不是完整功能验证。</p><h2 id="与上科大课程配合" tabindex="-1">与上科大课程配合 <a class="header-anchor" href="#与上科大课程配合" aria-label="Permalink to &quot;与上科大课程配合&quot;">​</a></h2>',12)),n(a,{codes:"EE115B,EE113,EE113L,EE116,EE291F"}),t[1]||(t[1]=e("p",null,"EE115B 阶段用小题巩固逻辑与 HDL；EE113、EE113L 阶段关注晶体管、电路与版图层次；EE116 和 EE291F 可进一步连接可编程逻辑或数字实现流程。具体实验与工具以当学期课程大纲为准。本站参考了往届 EE115B HDL 练习与 Verilog 学习笔记，只提炼学习方法，不将其中某次考试范围作为长期承诺。",-1)),t[2]||(t[2]=e("h2",{id:"参考与来源",tabindex:"-1"},[r("参考与来源 "),e("a",{class:"header-anchor",href:"#参考与来源","aria-label":'Permalink to "参考与来源"'},"​")],-1)),t[3]||(t[3]=e("ul",null,[e("li",null,[e("a",{href:"https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm",target:"_blank",rel:"noreferrer"},"上科大信息学院 2026–2027 学年开课计划"),r("。")]),e("li",null,"HDLBits、MIT 与 Berkeley 官方课程入口见上表；往届笔记仅作为资源线索。")],-1))])}const m=d(s,[["render",c]]);export{E as __pageData,m as default};
